namespace MyMorningNews.Core.Helpers
{
    using System;

    /// <summary>
    /// Generates K-sortable, prefixed identifiers with PrettyId. Generated by src/Tools/codegen.
    /// Thread safety: generation is thread safe.
    /// </summary>
    public static class IdGenerator
    {
        #region Public-Members

        /// <summary>
        /// Identifier length including the prefix. Default 32.
        /// </summary>
        public static int IdLength { get; } = 32;

        #endregion

        #region Private-Members

        private static readonly PrettyId.IdGenerator _Generator = new PrettyId.IdGenerator();

        #endregion

        #region Public-Methods

        /// <summary>
        /// Generate an identifier with an arbitrary prefix.
        /// </summary>
        /// <param name="prefix">Prefix such as "top_".</param>
        /// <returns>Identifier.</returns>
        /// <exception cref="ArgumentNullException">prefix is null or empty.</exception>
        public static string Generate(string prefix)
        {
            if (String.IsNullOrWhiteSpace(prefix)) throw new ArgumentNullException(nameof(prefix));
            return _Generator.GenerateKSortable(prefix, IdLength);
        }

        /// <summary>
        /// Generate a Tenant identifier.
        /// </summary>
        /// <returns>Identifier.</returns>
        public static string GenerateTenantId()
        {
            return Generate(IdPrefixes.Tenant);
        }

        /// <summary>
        /// Generate a User identifier.
        /// </summary>
        /// <returns>Identifier.</returns>
        public static string GenerateUserId()
        {
            return Generate(IdPrefixes.User);
        }

        /// <summary>
        /// Generate a Credential identifier.
        /// </summary>
        /// <returns>Identifier.</returns>
        public static string GenerateCredentialId()
        {
            return Generate(IdPrefixes.Credential);
        }

        /// <summary>
        /// Generate a AuthSession identifier.
        /// </summary>
        /// <returns>Identifier.</returns>
        public static string GenerateAuthSessionId()
        {
            return Generate(IdPrefixes.AuthSession);
        }

        /// <summary>
        /// Generate a UserRole identifier.
        /// </summary>
        /// <returns>Identifier.</returns>
        public static string GenerateUserRoleId()
        {
            return Generate(IdPrefixes.UserRole);
        }

        /// <summary>
        /// Generate a Permission identifier.
        /// </summary>
        /// <returns>Identifier.</returns>
        public static string GeneratePermissionId()
        {
            return Generate(IdPrefixes.Permission);
        }

        /// <summary>
        /// Generate a RolePermissionMap identifier.
        /// </summary>
        /// <returns>Identifier.</returns>
        public static string GenerateRolePermissionMapId()
        {
            return Generate(IdPrefixes.RolePermissionMap);
        }

        /// <summary>
        /// Generate a UserRoleAssignment identifier.
        /// </summary>
        /// <returns>Identifier.</returns>
        public static string GenerateUserRoleAssignmentId()
        {
            return Generate(IdPrefixes.UserRoleAssignment);
        }

        /// <summary>
        /// Generate a CredentialScopeAssignment identifier.
        /// </summary>
        /// <returns>Identifier.</returns>
        public static string GenerateCredentialScopeAssignmentId()
        {
            return Generate(IdPrefixes.CredentialScopeAssignment);
        }

        /// <summary>
        /// Generate a AuditRecord identifier.
        /// </summary>
        /// <returns>Identifier.</returns>
        public static string GenerateAuditRecordId()
        {
            return Generate(IdPrefixes.AuditRecord);
        }

        /// <summary>
        /// Generate a VaultCredential identifier.
        /// </summary>
        /// <returns>Identifier.</returns>
        public static string GenerateVaultCredentialId()
        {
            return Generate(IdPrefixes.VaultCredential);
        }

        /// <summary>
        /// Generate a ModelEndpoint identifier.
        /// </summary>
        /// <returns>Identifier.</returns>
        public static string GenerateModelEndpointId()
        {
            return Generate(IdPrefixes.ModelEndpoint);
        }

        /// <summary>
        /// Generate a ModelAssignment identifier.
        /// </summary>
        /// <returns>Identifier.</returns>
        public static string GenerateModelAssignmentId()
        {
            return Generate(IdPrefixes.ModelAssignment);
        }

        /// <summary>
        /// Generate a LlmCall identifier.
        /// </summary>
        /// <returns>Identifier.</returns>
        public static string GenerateLlmCallId()
        {
            return Generate(IdPrefixes.LlmCall);
        }

        /// <summary>
        /// Generate a PromptTemplate identifier.
        /// </summary>
        /// <returns>Identifier.</returns>
        public static string GeneratePromptTemplateId()
        {
            return Generate(IdPrefixes.PromptTemplate);
        }

        /// <summary>
        /// Generate a PromptTemplateVersion identifier.
        /// </summary>
        /// <returns>Identifier.</returns>
        public static string GeneratePromptTemplateVersionId()
        {
            return Generate(IdPrefixes.PromptTemplateVersion);
        }

        /// <summary>
        /// Generate a RequestHistory identifier.
        /// </summary>
        /// <returns>Identifier.</returns>
        public static string GenerateRequestHistoryId()
        {
            return Generate(IdPrefixes.RequestHistory);
        }

        /// <summary>
        /// Generate a Request identifier.
        /// </summary>
        /// <returns>Identifier.</returns>
        public static string GenerateRequestId()
        {
            return Generate(IdPrefixes.Request);
        }

        #endregion
    }
}
